import{_ as o,c as s,o as a,aj as c}from"./chunks/framework.B-K7myP5.js";const u=JSON.parse('{"title":"分支别名","frontmatter":{"title":"分支别名","createTime":"2025/01/17 19:27:31","permalink":"/docs/composer/aliases.html","lastUpdated":"2026-01-22","tags":[],"link":"/docs/composer/官方文章/aliases","layout":"doc","sidebar":true,"aside":true,"prev":{"text":"为什么 Composer 不递归加载代码库？","link":"/docs/composer/常见问题/cant-composer-load-repositories-recursively"},"next":{"text":"版本限制","link":"/docs/composer/官方文章/versions"}},"headers":[],"params":{"pkg":"composer/官方文章/aliases","sidebar":[{"text":"常见问题","items":[{"text":"如何为我的框架自定义一个扩展包安装目录？","link":"/docs/composer/index"},{"text":"如何使用脚本安装 Composer？","link":"/docs/composer/常见问题/to-install-composer-programmatically"},{"text":"使用 root 用户来安装扩展包是否安全？如何安全地安装未认证渠道的扩展包？","link":"/docs/composer/常见问题/to-install-untrusted-packages-safely"},{"text":"我应该将 vendor 目录加入版本控制吗？","link":"/docs/composer/常见问题/i-commit-the-dependencies-in-my-vendor-directory"},{"text":"Composer 使用的是什么版本命名规范？","link":"/docs/composer/常见问题/version-numbering-system-does-composer-itself-use"},{"text":"为什么限制版本是最佳实践？","link":"/docs/composer/常见问题/are-unbound-version-constraints-a-bad-idea"},{"text":"为何版本限制与对比符、通配符配合使用是个糟糕的行为？","link":"/docs/composer/常见问题/are-version-constraints-combining-comparisons-and-wildcards-a-bad-idea"},{"text":"为什么 Composer 不递归加载代码库？","link":"/docs/composer/常见问题/cant-composer-load-repositories-recursively"}]},{"text":"官方文章","items":[{"text":"分支别名","link":"/docs/composer/官方文章/aliases"},{"text":"版本限制","link":"/docs/composer/官方文章/versions"},{"text":"自动加载器优化","link":"/docs/composer/官方文章/optimization"},{"text":"自定义安装器","link":"/docs/composer/官方文章/installers"},{"text":"使用 Satis 处理私有仓库","link":"/docs/composer/官方文章/private-packages-with-satis"},{"text":"HTTP 基础认证","link":"/docs/composer/官方文章/basic-authentication"},{"text":"创建 Composer 插件","link":"/docs/composer/官方文章/plugins"},{"text":"事件和自定义脚本","link":"/docs/composer/官方文章/scripts"},{"text":"故障排除","link":"/docs/composer/官方文章/troubleshooting"},{"text":"可执行二进制文件","link":"/docs/composer/官方文章/binaries"}]},{"text":"教程","items":[{"text":"简介","link":"/docs/composer/教程/intro"},{"text":"基本使用","link":"/docs/composer/教程/basic-usage"},{"text":"创建扩展包","link":"/docs/composer/教程/libraries"},{"text":"Composer 命令的使用","link":"/docs/composer/教程/cli"},{"text":"json 完全解析","link":"/docs/composer/教程/schema"},{"text":"扩展包源仓库","link":"/docs/composer/教程/repositories"},{"text":"配置信息","link":"/docs/composer/教程/config"},{"text":"社区","link":"/docs/composer/教程/community"}]}],"versions":[]},"relativePath":"docs/composer/官方文章/aliases.md","filePath":"docs/[pkg].md"}'),n={name:"docs/composer/官方文章/aliases.md"};function t(d,e,i,p,r,l){return a(),s("div",null,[...e[0]||(e[0]=[c(`<h1 id="别名" tabindex="-1">别名 <a class="header-anchor" href="#别名" aria-label="Permalink to “别名”">​</a></h1><h2 id="为什么要使用别名" tabindex="-1">为什么要使用别名？ <a class="header-anchor" href="#为什么要使用别名" aria-label="Permalink to “为什么要使用别名？”">​</a></h2><p>当你使用版本控制系统仓库时，你只能从那些看起来像版本的分支得到一个可比较的版本，例如　<code>2.0</code>　或　<code>2.0.x</code>　。对于　<code>master</code>　分支，你只能得到一个　<code>dev-master</code>　版本。对于　<code>bugfix</code>　分支，你将得到　<code>dev-bugfix</code>　版本。</p><p>如果你的　<code>master</code>　分支是用来标记　<code>1.0</code>　的开发流程，如　<code>1.0.1</code>　，　<code>1.0.2</code>　，　 <code>1.0.3</code>　等，依赖于你的库的包可能需要的是　<code>1.0.*</code>　。</p><p>如果有人想要使用最新的　<code>dev-master</code>　，将会遇到一个问题：有的包可能需要的是　<code>1.0.*</code>　，所以这两个将会导致冲突，因为 <code>dev-master</code>　并不匹配　<code>1.0.*</code>　。</p><h2 id="基于以上-别名出现了。分支别名" tabindex="-1">基于以上，别名出现了。 分支别名 <a class="header-anchor" href="#基于以上-别名出现了。分支别名" aria-label="Permalink to “基于以上，别名出现了。分支别名”">​</a></h2><p><code>dev-master</code> 分支是主 VCS 仓库中的一个。有些人会想要最新的主开发版本，这是很常见的。因此，Composer 允许您将 <code>dev-master</code> 分支别名为 <code>1.0.x-dev</code> 版本。它是通过在 <code>composer.json</code> 中指定 <code>extra</code> 下的 <code>branch-alias</code> 字段来完成的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;extra&quot;: {</span></span>
<span class="line"><span>        &quot;branch-alias&quot;: {</span></span>
<span class="line"><span>            &quot;dev-master&quot;: &quot;1.0.x-dev&quot;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>如果别名为不可比较的版本 （例如 dev-develop），则必须为分支名称添加前缀 <code>dev-</code> 。您也可以为可比较的版本添加别名（即以数字开头，以 <code>.x-dev</code> 结尾），但只作为更具体的版本。例如，1.x-dev 可以被别名为 1.2.x-dev。</p><p>别名必须是可比较的开发版本，并且 <code>branch-alias</code> 必须出现在它引用的分支上。对于 <code>dev-master</code> 您需要在 <code>master</code> 分支上提交它。</p><p>因此，很多人现在都需要 <code>1.0.*</code> 并且他将很乐意安装 <code>dev-master</code> 。</p><p>要使用分支别名，您必须拥有别名的包的存储库。如果要为第三方包添加别名而不维护它的分支，请使用，内联别名，如下所述。</p><h2 id="需要内联别名" tabindex="-1">需要内联别名 <a class="header-anchor" href="#需要内联别名" aria-label="Permalink to “需要内联别名”">​</a></h2><p>分支别名对于主要开发线非常有用。但是为了使用它们，您需要控制源存储库，并且需要提交对版本控制的更改。</p><p>当您想尝试某个库的错误修复时，这并不是很有趣，该库是本地项目的依赖项。</p><p>因此，您可以在 <code>require</code> and <code>require-dev</code> 字段中对包进行别名。假设您在 <code>monolog/monolog</code> 包中发现了一个错误。您在 GitHub 上克隆了 <a href="https://github.com/Seldaek/monolog" target="_blank" rel="noreferrer">Monolog</a> 并在一个名叫 <code>bugfix</code> 的分支中解决了这个问题。现在，您要在本地项目中安装该版本的 monolog 。</p><p>您使用的是 <code>symfony/monolog-bundle</code> ，需要 <code>monolog/monolog</code> 版本 <code>1.*</code> 。因此，您需要使用 <code>dev-bugfix</code> 来匹配该约束。 将其添加到项目的根 <code>composer.json</code> 中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;repositories&quot;: [</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;type&quot;: &quot;vcs&quot;,</span></span>
<span class="line"><span>            &quot;url&quot;: &quot;https://github.com/you/monolog&quot;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    ],</span></span>
<span class="line"><span>    &quot;require&quot;: {</span></span>
<span class="line"><span>        &quot;symfony/monolog-bundle&quot;: &quot;2.0&quot;,</span></span>
<span class="line"><span>        &quot;monolog/monolog&quot;: &quot;dev-bugfix as 1.0.x-dev&quot;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>这将从您的 Github 获取 <code>monolog/monolog</code> 的 <code>dev-bugfix</code> 的版本，并将其别名为 <code>1.0.x-dev</code> 。</p><blockquote><p>注意：内联别名是仅限 root 用户使用的功能。如果需要具有内联别名的包，则使用别名（<code>as</code> 的右侧）用作版本约束。 <code>as</code> 的左边部分被丢弃了。因此，如果 A 需要 B 和 B 需要 <code>monolog/monolog</code> 版本 <code>dev-bugfix 为 1.0.x-dev</code> ，则安装 A 也将使 B 也需要 <code>1.0.x-dev</code> ，其可能作为分支别名或实际的 <code>1.0</code> 分支存在。如果没有，则必须在 A 的 <code>composer.json</code> 中再次进行内联别名。</p></blockquote><blockquote><p>注意：应避免使用内联别名，尤其是对于已发布的包/库。如果您发现了错误，请尝试将您的修复程序合并到上游，这有助于避免使用您包的用户出现问题。</p></blockquote>`,21)])])}const k=o(n,[["render",t]]);export{u as __pageData,k as default};
